head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil21211";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil21211.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_38_txt", fn: function(){ return ((dma_irData.get("korengTpCd") ?? (() => { throw new Error("unresolved:" + "irData.korengTpCd"); })()) === '1'); } }, { id: "c_when_39_txt", fn: function(){ return ((dma_irData.get("korengTpCd") ?? (() => { throw new Error("unresolved:" + "irData.korengTpCd"); })()) === '2'); } }, { id: "c_when_44_txt", fn: function(){ return ((dma_irData.get("regStatCd") ?? (() => { throw new Error("unresolved:" + "irData.regStatCd"); })()) === '1'); } }, { id: "c_when_45_txt", fn: function(){ return ((dma_irData.get("regStatCd") ?? (() => { throw new Error("unresolved:" + "irData.regStatCd"); })()) === '2'); } }, { id: "c_when_46_txt", fn: function(){ return ((dma_irData.get("regStatCd") ?? (() => { throw new Error("unresolved:" + "irData.regStatCd"); })()) === '3'); } }, { id: "c_otherwise_47", fn: function(){ return (!(((dma_irData.get("regStatCd") ?? (() => { throw new Error("unresolved:" + "irData.regStatCd"); })()) === '1') || ((dma_irData.get("regStatCd") ?? (() => { throw new Error("unresolved:" + "irData.regStatCd"); })()) === '2') || ((dma_irData.get("regStatCd") ?? (() => { throw new Error("unresolved:" + "irData.regStatCd"); })()) === '3'))); } }, { id: "if_picYn", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "picYn") ?? (() => { throw new Error("unresolved:" + "attach.picYn"); })()) === 'Y'); } }, { id: "c_when_67", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "c_when_71", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS' || (dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLSX'); } }, { id: "c_when_75", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC' || (dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOCX'); } }, { id: "c_when_79", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT' || (dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPTX'); } }, { id: "c_when_83", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_87", fn: function(){ return (!(((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS' || (dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLSX') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC' || (dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOCX') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT' || (dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPTX') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'))); } }, { id: "if_picYn_2", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "picYn") ?? (() => { throw new Error("unresolved:" + "attach.picYn"); })()) !== 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_57", entity: "dlt_irDataIrDataAttachVO", countIds: [], cells: [{ childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] },
        { genId: "c_foreach_63", entity: "dlt_irDataIrDataAttachVO", countIds: [], cells: [{ childId: "__rc6", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc9", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc10", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc11", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — jldfil21211: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_irDataIrDataAttachVO.getCellData(0, "reoroomId") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachSeq") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileChgDdtm") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21211.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_FileDown_2_onclick
 * @description btn_FileDown_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_2_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_irDataIrDataAttachVO.getCellData(0, "reoroomId") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachSeq") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileChgDdtm") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21211.btn_FileDown_2_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21211.btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/irData.do",
        ref: "dma_SearchReq",
        target: "dlt_irDataIrDataAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    (document.irDataForm || { elements: [] }).action = '/company/irData.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRData');
    const nr = await scwin.tx_fn_Search();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21210/jldfil21210.xml", { "method": 'searchIRData' });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} resoroomId resoroomId
 * @param {*} attachSeq attachSeq
 * @param {*} attachFileChgDdtm attachFileChgDdtm
 * @param {String} attachFileNm attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (resoroomId, attachSeq, attachFileChgDdtm, attachFileNm) {
    $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    $c.util.getComponent('dma_SearchReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_SearchReq').set('attachFileChgDdtm', attachFileChgDdtm);
    $c.util.getComponent('dma_SearchReq').set('attachFileNm', attachFileNm);
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    await scwin.tx_fn_FileDown();
};
